#!/usr/bin/env python3
# -*- coding: utf-8 -*-
# patch20: members index page (verify-directory/members/) and the three doors
# that lead to it: top site nav, verify-directory nav, member page nav.
# Default is dry-run. --apply writes. Anchors expect exactly 1 hit each.
# Pure ASCII on purpose (macOS Python 3.9 tokenizer bug on long multibyte lines).
import sys, subprocess, tempfile, os, re

APPLY = "--apply" in sys.argv
EDITS = [('verify-directory/index.html', '      <a href="#registry">The list</a>\n      <a href="#listed">Get listed</a>', '      <a href="#registry">The list</a>\n      <a href="/verify-directory/members/">Members</a>\n      <a href="#listed">Get listed</a>', 'vd nav members link'), ('index.html', '<a href="/verify-directory/">MCP\u691c\u8a3c\u30ec\u30b8\u30b9\u30c8\u30ea</a>', '<a href="/verify-directory/">MCP\u691c\u8a3c\u30ec\u30b8\u30b9\u30c8\u30ea</a><a href="/verify-directory/members/?lang=ja">\u691c\u8a3c\u6e08\u307f\u4e00\u89a7</a>', 'top nav members link'), ('verify-directory/member.html', '    <a id="backlink" href="./">Back to the list</a>', '    <a id="memberslink" href="./members/">Members</a>\n    <a id="backlink" href="./">Back to the list</a>', 'member nav members link'), ('verify-directory/member.html', '  en: {\n    back: "Back to the list",', '  en: {\n    members: "Members",\n    back: "Back to the list",', 'member en label'), ('verify-directory/member.html', '  ja: {\n    back: "\u4e00\u89a7\u3078\u623b\u308b",', '  ja: {\n    members: "\u767b\u9332\u7c3f",\n    back: "\u30c7\u30a3\u30ec\u30af\u30c8\u30ea\u3078",', 'member ja label'), ('verify-directory/member.html', '  document.getElementById("backlink").textContent = T.back;', '  document.getElementById("backlink").textContent = T.back;\n  const ml = document.getElementById("memberslink");\n  ml.textContent = T.members;\n  ml.href = LANG === "ja" ? "./members/?lang=ja" : "./members/";', 'member setStatics wiring')]
MEMBERS_DIR = "verify-directory/members"
MEMBERS_PATH = MEMBERS_DIR + "/index.html"
MEMBERS_CONTENT = '<!doctype html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>The register | HORIZON SHIELD verify directory</title>\n<meta name="description" content="Every server on the HORIZON SHIELD register, with its latest nightly verdict and full public measurement history.">\n<style>\n:root{\n  --bg:#08080a; --bg-2:#0d0d10; --surface:#121216;\n  --line:rgba(255,255,255,.07); --line-2:rgba(255,255,255,.12);\n  --ink:#f4f4f5; --ink-2:#a9a9b3; --ink-3:#6f6f7a;\n  --mono:\'JetBrains Mono\',ui-monospace,SFMono-Regular,Menlo,monospace;\n  --sans:\'Inter\',system-ui,-apple-system,sans-serif;\n}\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:var(--bg);color:var(--ink);font-family:var(--sans);line-height:1.62;-webkit-font-smoothing:antialiased;\n  background-image:radial-gradient(900px 500px at 82% -8%,rgba(52,211,153,.10),transparent 60%);background-attachment:fixed}\n.wrap{max-width:940px;margin:0 auto;padding:0 26px}\na{color:inherit;text-decoration:none}\n.mono{font-family:var(--mono)}\nheader{position:sticky;top:0;background:rgba(8,8,10,.74);backdrop-filter:blur(14px);border-bottom:1px solid var(--line);z-index:20}\n.bar{display:flex;align-items:center;justify-content:space-between;height:58px}\n.logo{font-weight:700;font-size:15px}\n.logo .sub{color:var(--ink-3);font-weight:500;font-size:11px;font-family:var(--mono)}\n.nav{display:flex;gap:16px;font-size:13.5px;color:var(--ink-2);align-items:center}\n.nav a:hover{color:var(--ink)}\n.langbtn{border:1px solid var(--line-2);border-radius:999px;padding:3px 12px;font-size:12px}\n.hero{padding:46px 0 8px}\nh1{font-size:2rem;letter-spacing:-.025em;line-height:1.25}\n.lead{color:var(--ink-2);margin-top:12px;max-width:620px}\n.count{color:var(--ink-3);font-size:.82rem;margin-top:16px;font-family:var(--mono)}\n.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(290px,1fr));gap:14px;margin:22px 0 8px}\n.mcard{display:block;background:var(--surface);border:1px solid var(--line-2);border-radius:12px;padding:18px 20px;transition:border-color .15s}\n.mcard:hover{border-color:var(--ink-3)}\n.mtop{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}\n.mname{font-weight:650;font-size:1rem;line-height:1.35}\n.mja{color:var(--ink-3);font-size:.78rem;margin-top:3px}\n.badge{flex-shrink:0;font-size:.7rem;padding:2px 9px;border-radius:999px;border:1px solid;white-space:nowrap}\n.b-pass{color:#7ee2a8;border-color:#2f6f4a}\n.b-pend{color:#e2c97e;border-color:#6f5c2f}\n.b-none{color:#9aa4b2;border-color:#3a4250}\n.mep{color:var(--ink-3);font-size:.68rem;font-family:var(--mono);margin-top:10px;word-break:break-all}\n.mmeta{color:var(--ink-2);font-size:.75rem;margin-top:8px}\n.card{background:var(--surface);border:1px solid var(--line-2);border-radius:14px;padding:24px;margin:26px 0}\nh2{font-size:1.05rem;margin-bottom:10px}\n.note{color:var(--ink-2);font-size:.84rem;margin:8px 0}\n.cta{display:inline-block;margin-top:12px;border:1px solid var(--line-2);border-radius:8px;padding:8px 16px;font-size:.85rem;color:var(--ink-2)}\n.cta:hover{color:var(--ink);border-color:var(--ink-3)}\nfooter{color:var(--ink-3);font-size:.78rem;padding:26px 0 50px}\n</style>\n</head>\n<body>\n<header><div class="wrap bar">\n  <div class="logo">HORIZON SHIELD <span class="sub">/ verify</span></div>\n  <div class="nav">\n    <a id="dirlink" href="../">Directory</a>\n    <a id="getlisted" href="../#listed">Get listed</a>\n    <a id="langbtn" class="langbtn" href="#">\u65e5\u672c\u8a9e</a>\n  </div>\n</div></header>\n\n<div class="wrap hero">\n  <h1 id="h1">The register</h1>\n  <p class="lead" id="lead"></p>\n  <p class="count" id="count"></p>\n</div>\n\n<div class="wrap">\n  <div class="grid" id="grid"></div>\n  <div class="card">\n    <h2 id="lh"></h2>\n    <p class="note" id="l1"></p>\n    <p class="note" id="l2"></p>\n    <a class="cta" id="cta" href="../#listed"></a>\n  </div>\n  <footer>Public code: <a class="mono" href="https://github.com/ogasurfproject-jpg/horizon-shield" rel="noopener" style="color:var(--ink-2)">github.com/ogasurfproject-jpg/horizon-shield</a></footer>\n</div>\n\n<script>\nconst GATE = "https://gate.horizonshield.dev";\nconst qs = new URLSearchParams(location.search);\nconst LANG = qs.get("lang") === "ja" ? "ja" : "en";\nconst STR = {\n  en: {\n    dir: "Directory", listed: "Get listed", langbtn: "\u65e5\u672c\u8a9e",\n    h1: "The register",\n    lead: "Every server measured by the gate, with its latest nightly verdict and its full public history. Listing is not endorsement, and absence is not a negative verdict.",\n    count: function(n){ return n + " rows on the register right now"; },\n    loading: "Reading the register\u2026",\n    zero: "The register answered with zero rows. That is the state of the register, not an error.",\n    fail: function(e){ return "The instrument could not read (" + e + "). No verdict is made. The register answers directly at " + GATE + "/register"; },\n    notyet: "not measured yet",\n    meas: function(n){ return n + (n === 1 ? " public measurement" : " public measurements"); },\n    lh: "What a row here means",\n    l1: "Rows are scheduled measurements, not endorsements. A green row means the conditions that were measured passed on that date. It does not mean the numbers a server returns are correct, or that the business behind it is any good.",\n    l2: "Every verdict carries a record_sha256 anyone can recompute. Open any member page and the command is right there. No trust in the operator is required.",\n    cta: "Put your own server on this list"\n  },\n  ja: {\n    dir: "\u30c7\u30a3\u30ec\u30af\u30c8\u30ea", listed: "\u63b2\u8f09\u3092\u7533\u3057\u8fbc\u3080", langbtn: "English",\n    h1: "\u767b\u9332\u7c3f",\n    lead: "\u691c\u8a3c\u30b2\u30fc\u30c8\u304c\u6e2c\u3063\u3066\u3044\u308b\u5168\u30b5\u30fc\u30d0\u30fc\u3068\u3001\u6bce\u6669\u306e\u6700\u65b0\u5224\u5b9a\u3001\u305d\u3057\u3066\u5168\u3066\u306e\u516c\u958b\u5c65\u6b74\u3002\u63b2\u8f09\u306f\u63a8\u85a6\u3067\u306f\u306a\u3044\u3002\u672a\u63b2\u8f09\u3082\u4e0d\u5408\u683c\u3067\u306f\u306a\u3044\u3002",\n    count: function(n){ return "\u73fe\u5728 " + n + " \u884c"; },\n    loading: "\u767b\u9332\u7c3f\u3092\u8aad\u307f\u8fbc\u307f\u4e2d\u2026",\n    zero: "\u767b\u9332\u7c3f\u306f0\u884c\u3068\u7b54\u3048\u305f\u3002\u3053\u308c\u306f\u767b\u9332\u7c3f\u306e\u72b6\u614b\u3067\u3042\u3063\u3066\u3001\u30a8\u30e9\u30fc\u3067\u306f\u306a\u3044\u3002",\n    fail: function(e){ return "\u8a08\u5668\u304c\u8aad\u3081\u306a\u304b\u3063\u305f\uff08" + e + "\uff09\u3002\u5224\u5b9a\u306f\u3057\u306a\u3044\u3002\u767b\u9332\u7c3f\u306f " + GATE + "/register \u3067\u76f4\u63a5\u8aad\u3081\u308b\u3002"; },\n    notyet: "\u672a\u6e2c\u5b9a",\n    meas: function(n){ return "\u516c\u958b\u6e2c\u5b9a " + n + " \u56de"; },\n    lh: "\u3053\u306e1\u884c\u304c\u610f\u5473\u3059\u308b\u3053\u3068",\n    l1: "\u5404\u884c\u306f\u4e88\u5b9a\u3055\u308c\u305f\u6e2c\u5b9a\u306e\u8a18\u9332\u3067\u3042\u3063\u3066\u3001\u63a8\u85a6\u3067\u306f\u306a\u3044\u3002\u7dd1\u306f\u300c\u6e2c\u5b9a\u3057\u305f\u6761\u4ef6\u304c\u305d\u306e\u65e5\u306f\u901a\u3063\u305f\u300d\u3068\u3044\u3046\u610f\u5473\u3060\u3002\u8fd4\u3055\u308c\u308b\u6570\u5b57\u304c\u6b63\u3057\u3044\u3053\u3068\u3082\u3001\u305d\u306e\u88cf\u306e\u5546\u58f2\u304c\u826f\u3044\u3053\u3068\u3082\u610f\u5473\u3057\u306a\u3044\u3002",\n    l2: "\u5168\u3066\u306e\u5224\u5b9a\u306b\u306f\u8ab0\u3067\u3082\u518d\u8a08\u7b97\u3067\u304d\u308b record_sha256 \u304c\u4ed8\u304f\u3002\u5404\u30da\u30fc\u30b8\u3092\u958b\u3051\u3070\u691c\u8a3c\u30b3\u30de\u30f3\u30c9\u304c\u305d\u306e\u307e\u307e\u7f6e\u3044\u3066\u3042\u308b\u3002\u904b\u55b6\u8005\u3092\u4fe1\u7528\u3059\u308b\u5fc5\u8981\u306f\u306a\u3044\u3002",\n    cta: "\u81ea\u5206\u306e\u30b5\u30fc\u30d0\u30fc\u3092\u3053\u306e\u4e00\u89a7\u306b\u8f09\u305b\u308b"\n  }\n};\nconst T = STR[LANG];\nfunction el(tag, cls, text){\n  const e = document.createElement(tag);\n  if (cls) e.className = cls;\n  if (text !== undefined) e.textContent = text;\n  return e;\n}\nfunction badgeClass(s){\n  return s === "pass" ? "b-pass" : (s === "pending" || s === "held") ? "b-pend" : "b-none";\n}\nfunction setStatics(){\n  document.documentElement.lang = LANG;\n  document.title = (LANG === "ja" ? "\u767b\u9332\u7c3f" : "The register") + " | HORIZON SHIELD verify directory";\n  document.getElementById("dirlink").textContent = T.dir;\n  document.getElementById("getlisted").textContent = T.listed;\n  const lb = document.getElementById("langbtn");\n  lb.textContent = T.langbtn;\n  lb.href = LANG === "ja" ? "./" : "./?lang=ja";\n  document.getElementById("h1").textContent = T.h1;\n  document.getElementById("lead").textContent = T.lead;\n  document.getElementById("count").textContent = T.loading;\n  document.getElementById("lh").textContent = T.lh;\n  document.getElementById("l1").textContent = T.l1;\n  document.getElementById("l2").textContent = T.l2;\n  document.getElementById("cta").textContent = T.cta;\n}\nasync function main(){\n  setStatics();\n  const grid = document.getElementById("grid");\n  const count = document.getElementById("count");\n  try{\n    const data = await (await fetch(GATE + "/register")).json();\n    const rows = Array.isArray(data.rows) ? data.rows : [];\n    if (!rows.length){ count.textContent = T.zero; return; }\n    count.textContent = T.count(rows.length);\n    rows.forEach(function(r){\n      const lb = r.operator_label || {};\n      const primary = LANG === "ja" ? (lb.ja || lb.en || r.endpoint) : (lb.en || lb.ja || r.endpoint);\n      const secondary = LANG === "ja" ? lb.en : lb.ja;\n      const a = el("a", "mcard");\n      a.href = "../member.html?endpoint=" + encodeURIComponent(r.endpoint) + (LANG === "ja" ? "&lang=ja" : "");\n      const top = el("div", "mtop");\n      const names = el("div");\n      names.appendChild(el("div", "mname", primary));\n      if (secondary && secondary !== primary) names.appendChild(el("div", "mja", secondary));\n      top.appendChild(names);\n      const stat = (r.latest && r.latest.status) ? r.latest.status : T.notyet;\n      top.appendChild(el("span", "badge " + badgeClass(stat), stat));\n      a.appendChild(top);\n      a.appendChild(el("div", "mep", r.endpoint));\n      if (typeof r.measurements === "number") a.appendChild(el("div", "mmeta", T.meas(r.measurements)));\n      grid.appendChild(a);\n    });\n  }catch(e){\n    count.textContent = T.fail(e.message);\n  }\n}\ndocument.addEventListener("DOMContentLoaded", main);\n</script>\n</body>\n</html>\n'

def main():
    contents = {}
    ok = True
    for path, old, new, name in EDITS:
        if path not in contents:
            contents[path] = open(path, encoding="utf-8").read()
        n = contents[path].count(old)
        print("[anchor] %s: %d occurrence(s) (expect 1)" % (name, n))
        if n != 1: ok = False
    exists = os.path.exists(MEMBERS_PATH)
    print("[anchor] members/index.html not present yet: %s (expect yes)" % ("yes" if not exists else "NO, already exists"))
    if exists: ok = False
    if not ok:
        print("ABORT: anchor mismatch. Nothing written.")
        sys.exit(1)
    for path, old, new, name in EDITS:
        contents[path] = contents[path].replace(old, new, 1)

    vd = contents["verify-directory/index.html"]
    top = contents["index.html"]
    mem = contents["verify-directory/member.html"]
    checks = [
        (vd.count("/verify-directory/members/") == 1, "vd: one members link"),
        (top.count("/verify-directory/members/?lang=ja") == 1, "top: one members link"),
        (mem.count("memberslink") == 2, "member: nav element and wiring"),
        (mem.count("members:") == 2, "member: label in both languages"),
        ("../member.html?endpoint=" in MEMBERS_CONTENT, "members: cards link to detail pages"),
        ("record_sha256" in MEMBERS_CONTENT, "members: honesty note mentions the hash"),
        ("Listing is not endorsement" in MEMBERS_CONTENT, "members: english honesty note"),
        ("\u63b2\u8f09\u306f\u63a8\u85a6\u3067\u306f\u306a\u3044" in MEMBERS_CONTENT, "members: japanese honesty note"),
    ]
    m = re.search(r"<script>(.*?)</script>", MEMBERS_CONTENT, re.S)
    tf = tempfile.NamedTemporaryFile("w", suffix=".js", delete=False, encoding="utf-8"); tf.write(m.group(1)); tf.close()
    r = subprocess.run(["node", "--check", tf.name], capture_output=True, text=True)
    os.unlink(tf.name)
    checks.append((r.returncode == 0, "members: node --check ok" + ("" if r.returncode == 0 else " :: " + r.stderr.strip()[:200])))
    m2 = re.search(r"<script>(.*?)</script>", mem, re.S)
    tf = tempfile.NamedTemporaryFile("w", suffix=".js", delete=False, encoding="utf-8"); tf.write(m2.group(1)); tf.close()
    r2 = subprocess.run(["node", "--check", tf.name], capture_output=True, text=True)
    os.unlink(tf.name)
    checks.append((r2.returncode == 0, "member: node --check still ok" + ("" if r2.returncode == 0 else " :: " + r2.stderr.strip()[:200])))
    allok = True
    for good, label in checks:
        print(("[ok]  " if good else "[FAIL] ") + label)
        allok = allok and good
    if not allok:
        print("ABORT: invariant failed. Nothing written.")
        sys.exit(1)
    if not APPLY:
        print("DRY-RUN OK. Nothing written. Run with --apply to write.")
        return
    for path in contents:
        open(path, "w", encoding="utf-8").write(contents[path])
        print("[written] " + path)
    if not os.path.isdir(MEMBERS_DIR):
        os.makedirs(MEMBERS_DIR)
        print("[created] " + MEMBERS_DIR + "/")
    open(MEMBERS_PATH, "w", encoding="utf-8").write(MEMBERS_CONTENT)
    print("[written] " + MEMBERS_PATH)
    print("APPLY done.")

if __name__ == "__main__":
    main()
